#include <cstdlib>
#include <algorithm>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>
#include <stdexcept>
#include "search.hpp"
#include "movegen.hpp"
#include "egdb/egdb.hpp"
#include "movetext.hpp"
using namespace regicide;
std::vector<std::string> split(const std::string&s,char c='\t'){std::vector<std::string>v;std::istringstream ss(s);for(std::string x;std::getline(ss,x,c);)v.push_back(x);return v;}
struct Game{std::string id,fen;int nopen;Color ours=BLACK;std::vector<std::string>moves;};
std::map<std::string,Game> load(const std::string&base){std::ifstream in(base+"/losses.tsv");std::map<std::string,Game>gs;for(std::string l;std::getline(in,l);){auto f=split(l);Game g;g.id=f[0];g.fen=f[1];g.nopen=std::stoi(f[2]);g.ours=f.size()>4&&f[4]=="W"?WHITE:BLACK;std::istringstream ms(f[3]);for(std::string m;ms>>m;)g.moves.push_back(m);gs[g.id]=g;}return gs;}
Position replay(const Game&g,int ply,std::vector<Position>*h=nullptr){Position p;if(!g.fen.empty()&&!p.set_fen(g.fen))throw std::runtime_error("FEN");for(int i=0;i<ply;++i){Move m;if(!parse_move(p,g.moves.at(i),m)||booklab::matching_moves(p,g.moves[i])!=1)throw std::runtime_error("bad move");if(h)h->push_back(p);p.make_move(m);}return p;}
std::string pvt(Position p,const std::vector<Move>&pv){std::string s;for(auto m:pv){MoveList ml;generate_moves(p,ml);if(std::find(ml.begin(),ml.end(),m)==ml.end())throw std::runtime_error("PV");s+=(s.empty()?"":" ")+move_text(p,m);p.make_move(m);}return s;}
int main(int argc,char**argv){try{if(argc<3)return 2;std::string mode=argv[1],base=argv[2];if(!egdb::init(std::getenv("REGICIDE_REVIEW_DB")?std::getenv("REGICIDE_REVIEW_DB"):"egdb",64))throw std::runtime_error("DB");auto gs=load(base);
 if(mode=="prepare"){std::ofstream roots(base+"/roots.tsv"),occ(base+"/occurrences.tsv");roots<<"id\tgame\tply\tpieces\tfen\trev\tlegal\tdb\n";occ<<"game\tply\tid\tplayed\tlegal\tpieces\tdb\n";std::map<std::string,std::string>seen;int nr=0,nforced=0;for(auto&[gid,g]:gs){(void)replay(g,g.moves.size());std::vector<Position>hist;Position p; if(!g.fen.empty())p.set_fen(g.fen);bool done=false;for(int i=0;i<int(g.moves.size());++i){Move m;if(!parse_move(p,g.moves[i],m))return 3;if(i>=g.nopen&&p.side_to_move()==g.ours&&!done){MoveList ml;generate_moves(p,ml);auto w=p.piece_count()<=7?egdb::probe(p.pieces(BLACK),p.pieces(WHITE),p.kings(),p.side_to_move()):egdb::Wld::Unknown;std::string sig=p.fen()+";"+std::to_string(p.reversible_plies());int n=std::min<int>(p.reversible_plies(),hist.size());for(int k=int(hist.size())-n;k<int(hist.size());++k)sig+=';'+hist[k].fen();std::string id;if(auto it=seen.find(sig);it!=seen.end())id=it->second;else{std::ostringstream ss;ss<<'R'<<nr++;id=ss.str();seen[sig]=id;roots<<id<<'\t'<<gid<<'\t'<<i<<'\t'<<p.piece_count()<<'\t'<<p.fen()<<'\t'<<p.reversible_plies()<<'\t'<<ml.size()<<'\t'<<int(w)<<'\n';}occ<<gid<<'\t'<<i<<'\t'<<id<<'\t'<<move_text(p,m)<<'\t'<<ml.size()<<'\t'<<p.piece_count()<<'\t'<<int(w)<<'\n';if(ml.size()==1)++nforced;if(w==egdb::Wld::Loss)done=true;}hist.push_back(p);p.make_move(m);}}
 std::cout<<"unique roots "<<nr<<" forced occurrences "<<nforced<<'\n';return 0;}
 if(argc!=9)return 2;std::string id=argv[3],net=argv[4],move=argv[7],path=argv[8];auto budget=std::stoull(argv[5]);if(budget>100000000)throw std::runtime_error("budget exceeds resumed 100M limit");int depth=std::stoi(argv[6]);std::ifstream in(base+"/roots.tsv");std::vector<std::string>f;for(std::string s;std::getline(in,s);){auto a=split(s);if(a[0]==id){f=a;break;}}if(f.empty())throw std::runtime_error("id");std::vector<Position>hist;auto p=replay(gs.at(f[1]),std::stoi(f[2]),&hist);auto ev=Evaluator::from_file(net=="n6c"?(std::getenv("REGICIDE_REVIEW_N6")?std::getenv("REGICIDE_REVIEW_N6"):"master/src/weights/net.bin"):net=="n9h"?"truth/experiments/truth-data/n9h.nnue":"truth/experiments/truth-data/n8q.nnue");if(!ev)throw std::runtime_error("net");Engine e;e.set_threads(1);e.set_hash_mb(128);e.set_evaluator(ev);e.set_egdb_pieces(7);e.set_book(nullptr);e.set_avoid(nullptr);e.new_game();e.set_position(p,hist);Limits l;l.nodes=budget==100000000?budget-1024:budget;l.depth=depth;l.movetime_ms=60000;l.use_book=false;if(mode=="root"){MoveList all;generate_moves(p,all);if(all.size()==1)l.searchmoves.assign(all.begin(),all.end());}if(mode=="force"){Move m;if(!parse_move(p,move,m))throw std::runtime_error("force");l.searchmoves={m};l.infinite=true;}
 SearchInfo c;std::vector<SearchInfo> steps;auto r=e.go(l,[&](const SearchInfo&i){c=i;steps.push_back(i);});if(r.depth!=c.depth)throw std::runtime_error("depth");{std::ofstream trace(path+".iterations.tsv");trace<<"depth\tscore\tmove\tnodes\tpv\n";for(const auto&i:steps)trace<<i.depth<<'\t'<<i.score<<'\t'<<(i.pv.empty()?"none":move_text(p,i.pv[0]))<<'\t'<<i.nodes<<'\t'<<pvt(p,i.pv)<<'\n';}std::ofstream out(path);out<<"id\tnet\tmode\tbudget\ttarget\tdepth\tscore\tactual_score\tpartial\tmove\tactual_move\tnodes\tms\ttbhits\tstatic\tpv\n"<<id<<'\t'<<net<<'\t'<<mode<<'\t'<<budget<<'\t'<<depth<<'\t'<<c.depth<<'\t'<<c.score<<'\t'<<r.score<<'\t'<<r.partial<<'\t'<<(c.pv.empty()?"none":move_text(p,c.pv[0]))<<'\t'<<move_text(p,r.best)<<'\t'<<r.nodes<<'\t'<<r.time_ms<<'\t'<<c.tbhits<<'\t'<<(*ev)(p)<<'\t'<<pvt(p,c.pv)<<'\n';return mode=="force"&&c.depth!=depth?8:0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 9;}}
